mapper.select:
SELECT id
FROM analysis_outbox
WHERE status = 'PENDING'
  AND next_attempt_at <= #{now}
ORDER BY id
LIMIT #{limit}

mapper.update:
UPDATE analysis_outbox
SET status = 'PROCESSING',
    updated_at = #{now}
WHERE id = #{id}
  AND status = 'PENDING'
  AND next_attempt_at <= #{now}

UPDATE analysis_outbox
SET status = 'PENDING',
    next_attempt_at = #{now},
    updated_at = #{now}
WHERE status = 'PROCESSING'
  AND updated_at < #{cutoff}
